CREATE TABLE licenses(id TEXT PRIMARY KEY,key_hash TEXT NOT NULL UNIQUE,expires_at INTEGER NOT NULL,seats INTEGER NOT NULL CHECK(seats>0),offline_seconds INTEGER NOT NULL CHECK(offline_seconds>=1),revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL CHECK(status IN('active','revoked')),created_at INTEGER NOT NULL);
CREATE TABLE activations(id TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES licenses(id),device_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('active','revoked')),created_at INTEGER NOT NULL,UNIQUE(license_id,device_id));
CREATE INDEX activation_seats ON activations(license_id,status);
CREATE TRIGGER activation_valid BEFORE INSERT ON activations WHEN (SELECT status FROM licenses WHERE id=NEW.license_id) != 'active' OR (SELECT expires_at FROM licenses WHERE id=NEW.license_id) <= unixepoch() BEGIN SELECT RAISE(ABORT,'license unavailable'); END;
CREATE TRIGGER policy_seats BEFORE UPDATE OF seats ON licenses WHEN NEW.seats < (SELECT count(*) FROM activations WHERE license_id=NEW.id AND status='active') BEGIN SELECT RAISE(ABORT,'seat unavailable'); END;
CREATE TRIGGER seat_limit BEFORE INSERT ON activations WHEN NEW.status='active' AND (SELECT count(*) FROM activations WHERE license_id=NEW.license_id AND status='active') >= (SELECT seats FROM licenses WHERE id=NEW.license_id) BEGIN SELECT RAISE(ABORT,'seat unavailable'); END;
CREATE TABLE revocations(id TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES licenses(id),activation_id TEXT REFERENCES activations(id),created_at INTEGER NOT NULL,actor TEXT NOT NULL);
CREATE TABLE admin_audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,license_id TEXT NOT NULL REFERENCES licenses(id),created_at INTEGER NOT NULL,details TEXT NOT NULL);
CREATE TABLE rate_buckets(bucket_key TEXT PRIMARY KEY,window INTEGER NOT NULL,count INTEGER NOT NULL);
CREATE TABLE requests(request_id TEXT PRIMARY KEY,license_id TEXT NOT NULL REFERENCES licenses(id),device_id TEXT NOT NULL,activation_id TEXT NOT NULL REFERENCES activations(id),created_at INTEGER NOT NULL);
CREATE TRIGGER request_identity BEFORE INSERT ON requests WHEN EXISTS(SELECT 1 FROM requests WHERE request_id=NEW.request_id AND (license_id!=NEW.license_id OR device_id!=NEW.device_id)) BEGIN SELECT RAISE(ABORT,'request unavailable'); END;
